#define DT 0.001f
#define OUT_ERR_SUM_MAX 500
#define OUT_I_ERR_MIN -OUT_ERR_SUM_MAX

// axis->out.reference: desired angle
// angle: measured rotation angle from IMU
void pid_outer_update(PIDDouble *axis, float set_point_angle, float angle)
{
    axis->out.reference = set_point_angle;
    axis->out.meas_value = angle;
    axis->out.error = axis->out.reference - axis->out.meas_value;

    axis->out.p_result = axis->out.error * axis->out.kp;

    axis->out.error_sum = axis->out.error_sum + axis->out.error * DT;
    if (axis->out.error_sum > OUT_ERR_SUM_MAX) axis->out.error_sum = OUT_ERR_SUM_MAX;
    else if (axis->out.error_sum < OUT_I_ERR_MIN) axis->out.error_sum = OUT_I_ERR_MIN;
    axis->out.i_result = axis->out.error_sum * axis->out.ki;

    axis->out.pid_result = axis->out.p_result + axis->out.i_result;
}
