// STM32 ADC is 12-bit (0-4095) and can only tolerate up to 3.3V,
// so a voltage divider steps the battery voltage down before it reaches the ADC pin.
float adc_to_battery_voltage(uint16_t analog_value)
{
    return (float)analog_value / 112.81f;
}
