// Filters out ESC-induced noise on the battery voltage ADC reading
float filter_battery_voltage(float previous_loop_voltage, uint16_t analog_value)
{
    return (previous_loop_voltage * 0.92f) + ((float)analog_value / 1410.1f);
}
