    float pitch_offset;
    float yaw_offset;
} gyro_calibration_t;

// Called once, at the moment the quadcopter is armed.
// The current gyro readings are taken as the zero-reference baseline
// and saved to EEPROM so the drone stabilizes relative to this state.
void save_gyro_calibration_to_eeprom(gyro_calibration_t *cal)
{
    eeprom_write_float(EEPROM_ADDR_ROLL_OFFSET, cal->roll_offset);
    eeprom_write_float(EEPROM_ADDR_PITCH_OFFSET, cal->pitch_offset);
    eeprom_write_float(EEPROM_ADDR_YAW_OFFSET, cal->yaw_offset);
}
